1	'use client'
2	
3	import { useState, useCallback, useEffect, useMemo } from 'react'
4	import { useSearchParams, useRouter } from 'next/navigation'
5	import { Users, SearchX, BookmarkX, Plus, Loader2 } from 'lucide-react'
6	import { toast } from 'sonner'
7	import { Button } from '@/components/ui/button'
8	import { ClientsTable } from '@/components/clients/ClientsTable'
9	import { ClientFilterBar, type ClientFilters } from '@/components/clients/ClientFilterBar'
10	import { BulkActionsBar } from '@/components/clients/BulkActionsBar'
11	import { SavedViewSwitcher, type ClientView } from '@/components/clients/SavedViewSwitcher'
12	import { SavedViewManager } from '@/components/clients/SavedViewManager'
13	import { ClientDrawer } from '@/components/clients/ClientDrawer'
14	import { Typography } from '@/components/ui/typography'
15	import { AddNoteModal } from '@/components/clients/notes/AddNoteModal'
16	import { DataState } from '@/components/shared/DataState'
17	import { EmptyState } from '@/components/shared/EmptyState'
18	import { PageError } from '@/components/shared/PageError'
19	import { TableSkeleton } from '@/components/skeletons'
20	import { Alert, AlertDescription } from '@/components/ui/alert'
21	import type { ClientTag } from '@/components/clients/TagChip'
22	import type { Database } from '@/lib/supabase/types'
23	
24	type Client = Database['public']['Tables']['clients']['Row']
25	
26	interface ClientsPageClientProps {
27	  initialClients: Client[]
28	  tagLibrary: ClientTag[]
29	}
30	
31	const DEFAULT_FILTERS: ClientFilters = {
32	  q: '',
33	  tags: [],
34	  vip: false,
35	  inactive: false,
36	  noShows: false,
37	  showArchived: false,
38	  spendingTier: '',
39	  artistIds: [],
40	  serviceIds: [],
41	  lastVisitRange: '',
42	}
43	
44	export function ClientsPageClient({ initialClients, tagLibrary }: ClientsPageClientProps) {
45	  const router = useRouter()
46	  const searchParams = useSearchParams()
47	
48	  const [clients, setClients] = useState<Client[]>(initialClients)
49	  const [filters, setFilters] = useState<ClientFilters>(DEFAULT_FILTERS)
50	  const [selectedIds, setSelectedIds] = useState<string[]>([])
51	  const [loading, setLoading] = useState(false)
52	  const [fetchError, setFetchError] = useState<Error | null>(null)
53	  const [drawerOpen, setDrawerOpen] = useState(false)
54	  const [editingClient, setEditingClient] = useState<Client | null>(null)
55	  const [noteClientId, setNoteClientId] = useState<string | null>(null)
56	  const [page, setPage] = useState(1)
57	  const [hasMore, setHasMore] = useState(false)
58	  const [totalCount, setTotalCount] = useState<number | null>(null)
59	
60	  // Saved views
61	  const [views, setViews] = useState<ClientView[]>([])
62	  const [activeViewId, setActiveViewId] = useState<string | null>(null)
63	  const [viewManagerOpen, setViewManagerOpen] = useState(false)
64	  const [viewManagerMode, setViewManagerMode] = useState<'create' | 'edit'>('create')
65	  const [editingView, setEditingView] = useState<ClientView | null>(null)
66	  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false)
67	
68	  const fetchViews = useCallback(async () => {
69	    try {
70	      const res = await fetch('/api/client-views')
71	      if (res.ok) {
72	        const json = await res.json() as { data: ClientView[] }
73	        setViews(json.data ?? [])
74	        // Auto-activate first system default view
75	        const defaultView = json.data?.find((v) => v.is_default)
76	        if (defaultView) {
77	          setActiveViewId((prev) => prev ?? defaultView.id)
78	        }
79	      }
80	    } catch {
81	      toast.error('Failed to load views', { description: 'Using All clients as default' })
82	    }
83	  }, [])
84	
85	  // Load saved views on mount
86	  useEffect(() => {
87	    void fetchViews()
88	  }, [fetchViews])
89	
90	  // Restore page from URL
91	  useEffect(() => {
92	    const p = parseInt(searchParams.get('page') ?? '1', 10)
93	    if (p > 1) {
94	      setPage(p)
95	    }
96	  }, []) // eslint-disable-line react-hooks/exhaustive-deps
97	
98	  const fetchClients = useCallback(async (f: ClientFilters, p = 1) => {
99	    setLoading(true)
100	    setFetchError(null)
101	    try {
102	      const params = new URLSearchParams()
103	      if (f.q) params.set('q', f.q)
104	      if (f.tags.length) params.set('tags', f.tags.join(','))
105	      if (f.vip) params.set('vip', 'true')
106	      if (f.inactive) params.set('inactive', 'true')
107	      if (f.noShows) params.set('no_show', 'true')
108	      if (!f.showArchived) params.set('archived', 'false')
109	      else params.set('archived', 'any')
110	      if (f.spendingTier) params.set('spending', f.spendingTier)
111	      if (f.artistIds.length) params.set('artist_ids', f.artistIds.join(','))
112	      if (f.serviceIds.length) params.set('service_ids', f.serviceIds.join(','))
113	      if (f.lastVisitRange) params.set('last_visit_range', f.lastVisitRange)
114	      params.set('page', String(p))
115	      params.set('per_page', '50')
116	
117	      const res = await fetch(`/api/clients?${params.toString()}`)
118	      if (!res.ok) throw new Error('Failed to load clients')
119	      const json = await res.json() as { data: Client[]; count: number }
120	
121	      if (p === 1) {
122	        setClients(json.data ?? [])
123	      } else {
124	        setClients((prev) => [...prev, ...(json.data ?? [])])
125	      }
126	      setTotalCount(json.count ?? null)
127	      setHasMore((json.data?.length ?? 0) >= 50)
128	    } catch (err) {
129	      setFetchError(err instanceof Error ? err : new Error('Failed to load clients'))
130	    } finally {
131	      setLoading(false)
132	    }
133	  }, [])
134	
135	  useEffect(() => {
136	    void fetchClients(filters, 1)
137	    setPage(1)
138	    setSelectedIds([])
139	  }, [filters, fetchClients])
140	
141	  function handleFiltersChange(f: ClientFilters) {
142	    setFilters(f)
143	    setHasUnsavedChanges(true)
144	  }
145	
146	  function handleViewChange(viewId: string | null) {
147	    setActiveViewId(viewId)
148	    setHasUnsavedChanges(false)
149	    const view = views.find((v) => v.id === viewId)
150	    if (view) {
151	      // Apply view filters
152	      const viewFilters = view.filters as Partial<ClientFilters>
153	      setFilters({ ...DEFAULT_FILTERS, ...viewFilters })
154	    } else {
155	      setFilters(DEFAULT_FILTERS)
156	    }
157	  }
158	
159	  async function handleDeleteView(viewId: string) {
160	    try {
161	      const res = await fetch(`/api/client-views/${viewId}`, { method: 'DELETE' })
162	      if (!res.ok) throw new Error('Failed to delete view')
163	      setViews((prev) => prev.filter((v) => v.id !== viewId))
164	      if (activeViewId === viewId) {
165	        const defaultView = views.find((v) => v.is_default)
166	        setActiveViewId(defaultView?.id ?? null)
167	      }
168	      toast.success('View deleted')
169	    } catch {
170	      toast.error('Failed to delete view')
171	    }
172	  }
173	
174	  async function handleDuplicateView(view: ClientView) {
175	    try {
176	      const res = await fetch('/api/client-views', {
177	        method: 'POST',
178	        headers: { 'Content-Type': 'application/json' },
179	        body: JSON.stringify({
180	          name: `${view.name} (copy)`,
181	          filters: view.filters,
182	          scope: 'private',
183	        }),
184	      })
185	      if (!res.ok) throw new Error('Failed to duplicate view')
186	      const json = await res.json() as { data: ClientView }
187	      setViews((prev) => [...prev, json.data])
188	      toast.success('View duplicated')
189	    } catch {
190	      toast.error('Failed to duplicate view')
191	    }
192	  }
193	
194	  function handleViewSaved(savedView: ClientView) {
195	    setViews((prev) => {
196	      const idx = prev.findIndex((v) => v.id === savedView.id)
197	      if (idx >= 0) {
198	        const next = [...prev]
199	        next[idx] = savedView
200	        return next
201	      }
202	      return [...prev, savedView]
203	    })
204	    setActiveViewId(savedView.id)
205	    setHasUnsavedChanges(false)
206	  }
207	
208	  function handleLoadMore() {
209	    const nextPage = page + 1
210	    setPage(nextPage)
211	    router.replace(`?page=${nextPage}`, { scroll: false })
212	    void fetchClients(filters, nextPage)
213	  }
214	
215	  function handleEditClient(client: Client) {
216	    setEditingClient(client)
217	    setDrawerOpen(true)
218	  }
219	
220	  function handleNewClient() {
221	    setEditingClient(null)
222	    setDrawerOpen(true)
223	  }
224	
225	  function handleDrawerSuccess(client: Client) {
226	    setClients((prev) => {
227	      const idx = prev.findIndex((c) => c.id === client.id)
228	      if (idx >= 0) {
229	        const next = [...prev]
230	        next[idx] = client
231	        return next
232	      }
233	      return [client, ...prev]
234	    })
235	  }
236	
237	  const hasActiveFilters = !!(
238	    filters.q || filters.tags.length > 0 || filters.vip ||
239	    filters.inactive || filters.noShows || filters.spendingTier ||
240	    filters.artistIds.length > 0 || filters.serviceIds.length > 0 || filters.lastVisitRange
241	  )
242	
243	  const inactiveCount = useMemo(() => {
244	    const cutoff = Date.now() - 90 * 24 * 60 * 60 * 1000
245	    return clients.filter(
246	      (c) => !c.archived_at && c.last_visit_at !== null && new Date(c.last_visit_at).getTime() < cutoff
247	    ).length
248	  }, [clients])
249	
250	  const activeView = views.find((v) => v.id === activeViewId) ?? null
251	  const isInitialLoad = loading && clients.length === 0
252	
253	  return (
254	    <div className="flex flex-col gap-4 p-4 lg:p-6">
255	      {/* Header */}
256	      <div className="flex items-center justify-between">
257	        <div className="flex items-center gap-3">
258	          <div>
259	            <Typography variant="h1">Clients</Typography>
260	            <p className="text-sm text-muted-foreground mt-0.5">
261	              {totalCount !== null ? (
262	                <span className="tabular-nums">
263	                  {clients.length} of {totalCount} client{totalCount !== 1 ? 's' : ''}
264	                </span>
265	              ) : clients.length > 0 ? (
266	                <span className="tabular-nums">{clients.length} client{clients.length !== 1 ? 's' : ''}</span>
267	              ) : null}
268	            </p>
269	          </div>
270	          {inactiveCount > 0 && (
271	            <span
272	              title={`${inactiveCount} client${inactiveCount !== 1 ? 's' : ''} not seen in 90+ days`}
273	              className="inline-flex items-center gap-1 rounded-full bg-destructive/10 text-destructive text-xs font-medium px-2 py-0.5 select-none"
274	            >
275	              <span className="h-2 w-2 rounded-full bg-destructive shrink-0" aria-hidden="true" />
276	              {inactiveCount} inactive
277	            </span>
278	          )}
279	        </div>
280	        <Button onClick={handleNewClient}>
281	          <Plus className="mr-2 h-4 w-4" aria-hidden="true" />
282	          New client
283	        </Button>
284	      </div>
285	
286	      {/* Saved views switcher */}
287	      {views.length > 0 && (
288	        <SavedViewSwitcher
289	          views={views}
290	          activeViewId={activeViewId}
291	          onViewChange={handleViewChange}
292	          onCreateView={() => {
293	            setViewManagerMode('create')
294	            setEditingView(null)
295	            setViewManagerOpen(true)
296	          }}
297	          onEditView={(view) => {
298	            setViewManagerMode('edit')
299	            setEditingView(view)
300	            setViewManagerOpen(true)
301	          }}
302	          onDuplicateView={handleDuplicateView}
303	          onDeleteView={handleDeleteView}
304	        />
305	      )}
306	
307	      {/* Unsaved changes banner */}
308	      {hasUnsavedChanges && activeView && !activeView.is_system && (
309	        <Alert className="py-2 border-amber-500/30 bg-amber-500/5">
310	          <AlertDescription className="flex items-center justify-between gap-3 text-xs">
311	            <span className="text-amber-700 dark:text-amber-400">
312	              Unsaved changes. Save view or discard?
313	            </span>
314	            <div className="flex gap-2 shrink-0">
315	              <Button
316	                size="sm"
317	                variant="outline"
318	                className="h-6 text-xs px-2"
319	                onClick={() => {
320	                  setFilters({ ...DEFAULT_FILTERS, ...(activeView.filters as Partial<ClientFilters>) })
321	                  setHasUnsavedChanges(false)
322	                }}
323	              >
324	                Discard
325	              </Button>
326	              <Button
327	                size="sm"
328	                className="h-6 text-xs px-2"
329	                onClick={() => {
330	                  setViewManagerMode('edit')
331	                  setEditingView(activeView)
332	                  setViewManagerOpen(true)
333	                }}
334	              >
335	                Save view
336	              </Button>
337	            </div>
338	          </AlertDescription>
339	        </Alert>
340	      )}
341	
342	      <ClientFilterBar
343	        filters={filters}
344	        onChange={handleFiltersChange}
345	        tagLibrary={tagLibrary}
346	      />
347	
348	      {selectedIds.length > 0 && (
349	        <BulkActionsBar
350	          selectedIds={selectedIds}
351	          tagLibrary={tagLibrary}
352	          onClearSelection={() => setSelectedIds([])}
353	          onArchived={() => void fetchClients(filters, 1)}
354	          onTagsApplied={() => void fetchClients(filters, 1)}
355	        />
356	      )}
357	
358	      <DataState
359	        data={clients}
360	        isLoading={isInitialLoad}
361	        isError={!!fetchError && clients.length === 0}
362	        error={fetchError}
363	        loadingSlot={<TableSkeleton rows={8} />}
364	        emptySlot={
365	          hasActiveFilters ? (
366	            <EmptyState
367	              icon={SearchX}
368	              title="No clients match these filters"
369	              description="Try different filters or clear all to see everyone."
370	              cta={{ label: 'Clear filters', onClick: () => { setFilters(DEFAULT_FILTERS); setHasUnsavedChanges(false) } }}
371	              variant="no-results"
372	            />
373	          ) : activeView && activeViewId ? (
374	            <EmptyState
375	              icon={BookmarkX}
376	              title="No clients in this view"
377	              description={`The filters in "${activeView.name}" returned no results.`}
378	              cta={{
379	                label: 'Edit view filters',
380	                onClick: () => {
381	                  setViewManagerMode('edit')
382	                  setEditingView(activeView)
383	                  setViewManagerOpen(true)
384	                },
385	              }}
386	              variant="no-results"
387	            />
388	          ) : (
389	            <EmptyState
390	              icon={Users}
391	              title="No clients yet"
392	              description="Add your first client or import from CSV — they'll show up here as they book."
393	              cta={{ label: '+ Add client', onClick: handleNewClient }}
394	              variant="first-time"
395	            />
396	          )
397	        }
398	        errorSlot={
399	          <PageError
400	            error={fetchError ?? new Error('Failed to load clients')}
401	            reset={() => void fetchClients(filters, 1)}
402	            variant="inline"
403	          />
404	        }
405	      >
406	        {(data) => (
407	          <ClientsTable
408	            clients={data}
409	            tagLibrary={tagLibrary}
410	            loading={loading && data.length === 0}
411	            selectedIds={selectedIds}
412	            onSelectionChange={setSelectedIds}
413	            onEdit={handleEditClient}
414	            onAddNote={(id) => setNoteClientId(id)}
415	          />
416	        )}
417	      </DataState>
418	
419	      {/* Load more */}
420	      {(hasMore || loading) && clients.length > 0 && (
421	        <div className="flex items-center justify-between py-4">
422	          <span className="text-sm text-muted-foreground tabular-nums">
423	            Showing {clients.length}{totalCount !== null ? ` of ${totalCount}` : ''} clients
424	          </span>
425	          {hasMore && (
426	            <Button variant="outline" size="sm" onClick={handleLoadMore} disabled={loading}>
427	              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" aria-hidden="true" />}
428	              Load more
429	            </Button>
430	          )}
431	        </div>
432	      )}
433	
434	      <ClientDrawer
435	        open={drawerOpen}
436	        onOpenChange={(v) => {
437	          setDrawerOpen(v)
438	          if (!v) setEditingClient(null)
439	        }}
440	        client={editingClient}
441	        tagLibrary={tagLibrary}
442	        onSuccess={handleDrawerSuccess}
443	      />
444	
445	      {noteClientId && (
446	        <AddNoteModal
447	          open={Boolean(noteClientId)}
448	          onOpenChange={(v) => { if (!v) setNoteClientId(null) }}
449	          clientId={noteClientId}
450	        />
451	      )}
452	
453	      <SavedViewManager
454	        open={viewManagerOpen}
455	        onOpenChange={setViewManagerOpen}
456	        mode={viewManagerMode}
457	        view={editingView}
458	        currentFilters={filters}
459	        onSaved={handleViewSaved}
460	      />
461	    </div>
462	  )
463	}
464
